INSERT INTO `category_translations` VALUES (1,1,'Root','root','','<p>Root Category Description</p>','','','',NULL,NULL,NULL,'en'),(2,2,'Flagship Smartphones','flagship-smartphones','','<p>World-class flagship smartphones featuring cutting-edge performance, latest-generation chipsets, and pro-grade camera systems.</p>','Flagship Smartphones','World-class flagship smartphones featuring cutting-edge performance, latest-generation chipsets, and pro-grade camera systems.','','',NULL,NULL,'en'),(3,3,'Fast Chargers & GaN','fast-chargers-gan','','<p>High-performance GaN fast chargers from 65W to 240W, multi-device fast charging for smartphones and laptops.</p>','Fast Chargers & GaN','High-performance GaN fast chargers from 65W to 240W, multi-device fast charging for smartphones and laptops.','','',NULL,NULL,'en'),(4,4,'Power Banks','power-banks','','<p>High-capacity 20,000mAh - 30,000mAh power banks with massive output power and futuristic Cyberpunk aesthetics.</p>','Power Banks','High-capacity 20,000mAh - 30,000mAh power banks with massive output power and futuristic Cyberpunk aesthetics.','','',NULL,NULL,'en'),(5,5,'Audio & Gaming Earbuds','audio-gaming-earbuds','','<p>True Wireless earbuds with active noise cancellation (ANC), Hi-Res LDAC certified audio, and ultra-low latency gaming audio.</p>','Audio & Gaming Earbuds','True Wireless earbuds with active noise cancellation (ANC), Hi-Res LDAC certified audio, and ultra-low latency gaming audio.','','',NULL,NULL,'en'),(6,6,'Phone Coolers & Gaming Gear','phone-coolers-gaming-gear','','<p>Magnetic semiconductor phone coolers with 27W - 36W power, instant drop to 0°C for uninterrupted maximum gaming performance.</p>','Phone Coolers & Gaming Gear','Magnetic semiconductor phone coolers with 27W - 36W power, instant drop to 0°C for uninterrupted maximum gaming performance.','','',NULL,NULL,'en'),(7,7,'Thunderbolt Cables & Hubs','cables-and-hubs','','<p>Heavy-duty braided Type-C Thunderbolt 4 240W cables with 40Gbps lightning-fast data transfer and multi-port expansion hubs.</p>','Thunderbolt Cables & Hubs','Heavy-duty braided Type-C Thunderbolt 4 240W cables with 40Gbps lightning-fast data transfer and multi-port expansion hubs.','','',NULL,NULL,'en'),(8,8,'Tough Cases & Screen Protectors','cases-and-protectors','','<p>Military-grade shockproof cases with authentic Kevlar MagSafe and ultra-tough 9H+ scratch-resistant tempered glass screen protectors.</p>','Tough Cases & Screen Protectors','Military-grade shockproof cases with authentic Kevlar MagSafe and ultra-tough 9H+ scratch-resistant tempered glass screen protectors.','','',NULL,NULL,'en'),(9,9,'TestOnly1','testonly1','','<p>I Never see him before :)</p>','test','','',NULL,NULL,1,'en'),(10,1,'Root','root','','<p>Root Category Description</p>','','','',NULL,NULL,2,'vi'),(11,2,'Flagship Smartphones','flagship-smartphones','','<p>World-class flagship smartphones featuring cutting-edge performance, latest-generation chipsets, and pro-grade camera systems.</p>','Flagship Smartphones','World-class flagship smartphones featuring cutting-edge performance, latest-generation chipsets, and pro-grade camera systems.','','',NULL,2,'vi'),(12,3,'Fast Chargers & GaN','fast-chargers-gan','','<p>High-performance GaN fast chargers from 65W to 240W, multi-device fast charging for smartphones and laptops.</p>','Fast Chargers & GaN','High-performance GaN fast chargers from 65W to 240W, multi-device fast charging for smartphones and laptops.','','',NULL,2,'vi'),(13,4,'Power Banks','power-banks','','<p>High-capacity 20,000mAh - 30,000mAh power banks with massive output power and futuristic Cyberpunk aesthetics.</p>','Power Banks','High-capacity 20,000mAh - 30,000mAh power banks with massive output power and futuristic Cyberpunk aesthetics.','','',NULL,2,'vi'),(14,5,'Audio & Gaming Earbuds','audio-gaming-earbuds','','<p>True Wireless earbuds with active noise cancellation (ANC), Hi-Res LDAC certified audio, and ultra-low latency gaming audio.</p>','Audio & Gaming Earbuds','True Wireless earbuds with active noise cancellation (ANC), Hi-Res LDAC certified audio, and ultra-low latency gaming audio.','','',NULL,2,'vi'),(15,6,'Phone Coolers & Gaming Gear','phone-coolers-gaming-gear','','<p>Magnetic semiconductor phone coolers with 27W - 36W power, instant drop to 0°C for uninterrupted maximum gaming performance.</p>','Phone Coolers & Gaming Gear','Magnetic semiconductor phone coolers with 27W - 36W power, instant drop to 0°C for uninterrupted maximum gaming performance.','','',NULL,2,'vi'),(16,7,'Thunderbolt Cables & Hubs','cables-and-hubs','','<p>Heavy-duty braided Type-C Thunderbolt 4 240W cables with 40Gbps lightning-fast data transfer and multi-port expansion hubs.</p>','Thunderbolt Cables & Hubs','Heavy-duty braided Type-C Thunderbolt 4 240W cables with 40Gbps lightning-fast data transfer and multi-port expansion hubs.','','',NULL,2,'vi'),(17,8,'Tough Cases & Screen Protectors','cases-and-protectors','','<p>Military-grade shockproof cases with authentic Kevlar MagSafe and ultra-tough 9H+ scratch-resistant tempered glass screen protectors.</p>','Tough Cases & Screen Protectors','Military-grade shockproof cases with authentic Kevlar MagSafe and ultra-tough 9H+ scratch-resistant tempered glass screen protectors.','','',NULL,2,'vi'),(18,9,'TestOnly1','testonly1','','<p>I Never see him before :)</p>','test','','',NULL,NULL,2,'vi'),(25,10,'Nước Hoa Nam','nuoc-hoa-nam','nuoc-hoa-nam','<p>Bộ sưu tập Nước Hoa Nam chính hãng cao cấp, lưu hương bền lâu.</p>','Nước Hoa Nam Chính Hãng Cao Cấp','Mua Nước Hoa Nam chính hãng, giá tốt nhất với nhiều ưu đãi.','Nước Hoa Nam, nuoc hoa chinh hang',NULL,NULL,2,'vi'),(26,10,'Men\'s Perfumes','mens-perfumes','mens-perfumes','<p>Authentic Men\'s Perfumes collection with long-lasting scent.</p>','Authentic Men\'s Perfumes','Buy authentic Men\'s Perfumes at best prices.','Men\'s Perfumes, authentic perfume',NULL,NULL,1,'en'),(27,11,'Nước Hoa Nữ','nuoc-hoa-nu','nuoc-hoa-nu','<p>Bộ sưu tập Nước Hoa Nữ chính hãng cao cấp, lưu hương bền lâu.</p>','Nước Hoa Nữ Chính Hãng Cao Cấp','Mua Nước Hoa Nữ chính hãng, giá tốt nhất với nhiều ưu đãi.','Nước Hoa Nữ, nuoc hoa chinh hang',NULL,NULL,2,'vi'),(28,11,'Women\'s Perfumes','womens-perfumes','womens-perfumes','<p>Authentic Women\'s Perfumes collection with long-lasting scent.</p>','Authentic Women\'s Perfumes','Buy authentic Women\'s Perfumes at best prices.','Women\'s Perfumes, authentic perfume',NULL,NULL,1,'en'),(29,12,'Nước Hoa Unisex','nuoc-hoa-unisex','nuoc-hoa-unisex','<p>Bộ sưu tập Nước Hoa Unisex chính hãng cao cấp, lưu hương bền lâu.</p>','Nước Hoa Unisex Chính Hãng Cao Cấp','Mua Nước Hoa Unisex chính hãng, giá tốt nhất với nhiều ưu đãi.','Nước Hoa Unisex, nuoc hoa chinh hang',NULL,NULL,2,'vi'),(30,12,'Unisex Perfumes','unisex-perfumes','unisex-perfumes','<p>Authentic Unisex Perfumes collection with long-lasting scent.</p>','Authentic Unisex Perfumes','Buy authentic Unisex Perfumes at best prices.','Unisex Perfumes, authentic perfume',NULL,NULL,1,'en'),(31,13,'Nước Hoa Chiết & Mini','nuoc-hoa-chiet-mini','nuoc-hoa-chiet-mini','<p>Bộ sưu tập Nước Hoa Chiết & Mini chính hãng cao cấp, lưu hương bền lâu.</p>','Nước Hoa Chiết & Mini Chính Hãng Cao Cấp','Mua Nước Hoa Chiết & Mini chính hãng, giá tốt nhất với nhiều ưu đãi.','Nước Hoa Chiết & Mini, nuoc hoa chinh hang',NULL,NULL,2,'vi'),(32,13,'Mini & Decant Perfumes','mini-decant-perfumes','mini-decant-perfumes','<p>Authentic Mini & Decant Perfumes collection with long-lasting scent.</p>','Authentic Mini & Decant Perfumes','Buy authentic Mini & Decant Perfumes at best prices.','Mini & Decant Perfumes, authentic perfume',NULL,NULL,1,'en');
