,NULL,NULL,NULL,NULL,NULL,3,26,'3|26'),(30,NULL,NULL,'0.35',NULL,NULL,NULL,NULL,NULL,NULL,3,22,'3|22'),(31,'en',NULL,'<p>The ultimate flagship gaming phone featuring an ultra-smooth 165Hz AMOLED display, AirTrigger ultrasonic touch sensors, and GameCool 8 3D vapor chamber cooling system.</p>',NULL,NULL,NULL,NULL,NULL,NULL,5,9,'en|5|9'),(32,'en',NULL,'<div class=\"tech-product-detail\" style=\"font-family:inherit;\">\r\n<p style=\"font-size:16px;margin-bottom:16px;\">The ultimate flagship gaming phone featuring an ultra-smooth 165Hz AMOLED display, AirTrigger ultrasonic touch sensors, and GameCool 8 3D vapor chamber cooling system.</p>\r\n<h3 style=\"font-size:18px;font-weight:bold;margin-top:24px;margin-bottom:12px;color:#111827;\">Technical Specifications</h3>\r\n<table style=\"width:100%;border-collapse:collapse;border:1px solid #e5e7eb;margin-bottom:24px;\">\r\n<tbody>\r\n<tr style=\"background-color:#f9fafb;border-bottom:1px solid #e5e7eb;\">\r\n<td style=\"padding:10px 16px;font-weight:600;width:35%;color:#374151;font-size:14px;\">Display</td>\r\n<td style=\"padding:10px 16px;color:#4b5563;font-size:14px;\">6.78 inch Samsung E6 Flexible AMOLED 165Hz LTPO 2500 nits</td>\r\n</tr>\r\n<tr style=\"background-color:#ffffff;border-bottom:1px solid #e5e7eb;\">\r\n<td style=\"padding:10px 16px;font-weight:600;width:35%;color:#374151;font-size:14px;\">Processor</td>\r\n<td style=\"padding:10px 16px;color:#4b5563;font-size:14px;\">Snapdragon 8 Gen 3 clocked up to 3.3GHz</td>\r\n</tr>\r\n<tr style=\"background-color:#f9fafb;border-bottom:1px solid #e5e7eb;\">\r\n<td style=\"padding:10px 16px;font-weight:600;width:35%;color:#374151;font-size:14px;\">Memory &amp; Storage</td>\r\n<td style=\"padding:10px 16px;color:#4b5563;font-size:14px;\">16GB LPDDR5X RAM, 512GB UFS 4.0 storage</td>\r\n</tr>\r\n<tr style=\"background-color:#ffffff;border-bottom:1px solid #e5e7eb;\">\r\n<td style=\"padding:10px 16px;font-weight:600;width:35%;color:#374151;font-size:14px;\">LED Lighting</td>\r\n<td style=\"padding:10px 16px;color:#4b5563;font-size:14px;\">AniMe Vision secondary matrix display with 341 customizable mini-LEDs</td>\r\n</tr>\r\n<tr style=\"background-color:#f9fafb;border-bottom:1px solid #e5e7eb;\">\r\n<td style=\"padding:10px 16px;font-weight:600;width:35%;color:#374151;font-size:14px;\">Battery &amp; Charging</td>\r\n<td style=\"padding:10px 16px;color:#4b5563;font-size:14px;\">5,500 mAh, 65W HyperCharge fast charging, 15W Qi wireless charging</td>\r\n</tr>\r\n<tr style=\"background-color:#ffffff;border-bottom:1px solid #e5e7eb;\">\r\n<td style=\"padding:10px 16px;font-weight:600;width:35%;color:#374151;font-size:14px;\">Gaming Features</td>\r\n<td style=\"padding:10px 16px;color:#4b5563;font-size:14px;\">AirTrigger 8, dual USB-C ports (side &amp; bottom), IP68 water resistance</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<div style=\"border-left:4px solid #3b82f6;padding:12px 16px;margin-top:16px;\">\r\n<p style=\"margin:0;color:#1e40af;font-size:13px;font-weight:500;\">✓ 100% Brand-New Genuine Sealed | 12-24 Month Official Warranty | 30-Day Replacement for Manufacturer Defects</p>\r\n</div>\r\n</div>',NULL,NULL,NULL,NULL,NULL,NULL,5,10,'en|5|10'),(33,NULL,NULL,'PHONE-ROG8PRO-512',NULL,NULL,NULL,NULL,NULL,NULL,5,1,'5|1'),(34,'en',NULL,'ASUS ROG Phone 8 Pro 16GB/512GB Gaming Snapdragon 8 Gen 3',NULL,NULL,NULL,NULL,NULL,NULL,5,2,'en|5|2'),(35,'en',NULL,'asus-rog-phone-8-pro-16gb512gb-gaming-snapdragon-8-gen-3-nom6',NULL,NULL,NULL,NULL,NULL,NULL,5,3,'en|5|3'),(36,NULL,'default',NULL,1,NULL,NULL,NULL,NULL,NULL,5,28,'default|5|28'),(37,NULL,NULL,NULL,NULL,NULL,1099.0000,NULL,NULL,NULL,5,11,'5|11'),(38,NULL,NULL,NULL,NULL,NULL,824.2500,NULL,NULL,NULL,5,12,'5|12'),(39,NULL,NULL,NULL,NULL,NULL,999.0000,NULL,NULL,NULL,5,13,'5|13'),(40,NULL,'default',NULL,NULL,NULL,NULL,NULL,'2025-01-01',NULL,5,14,'default|5|14'),(41,NULL,'default',NULL,NULL,NULL,NULL,NULL,'2027-12-31',NULL,5,15,'default|5|15'),(42,NULL,'default',NULL,0,NULL,NULL,NULL,NULL,NULL,5,29,'