94,NULL,NULL,'PERFUME-0181',NULL,NULL,NULL,NULL,NULL,NULL,121,1,'null|121|1'),(2895,'vi',NULL,'Nước Hoa Chiết Creed Aventus EDP 10ml',NULL,NULL,NULL,NULL,NULL,NULL,121,2,'vi|121|2'),(2896,'en',NULL,'Decant Creed Aventus EDP 10ml',NULL,NULL,NULL,NULL,NULL,NULL,121,2,'en|121|2'),(2897,'vi',NULL,'nuoc-hoa-chiet-creed-aventus-edp-10ml',NULL,NULL,NULL,NULL,NULL,NULL,121,3,'vi|121|3'),(2898,'en',NULL,'decant-creed-aventus-edp-10ml',NULL,NULL,NULL,NULL,NULL,NULL,121,3,'en|121|3'),(2899,NULL,NULL,NULL,1,NULL,NULL,NULL,NULL,NULL,121,5,'null|121|5'),(2900,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,121,6,'null|121|6'),(2901,NULL,NULL,NULL,1,NULL,NULL,NULL,NULL,NULL,121,7,'null|121|7'),(2902,NULL,NULL,NULL,1,NULL,NULL,NULL,NULL,NULL,121,8,'null|121|8'),(2903,'vi',NULL,'<p><strong>Nước Hoa Chiết Creed Aventus EDP 10ml</strong> chính hãng (Creed - Pháp). Phong cách: Hoàng gia, Đẳng cấp bỏ túi, Tiện dụng du lịch. Nồng độ Eau de Parfum (EDP), dung tích 10ml.</p>',NULL,NULL,NULL,NULL,NULL,NULL,121,9,'vi|121|9'),(2904,'en',NULL,'<p>Decant Creed Aventus EDP 10ml authentic - Luxurious, captivating scent.</p>',NULL,NULL,NULL,NULL,NULL,NULL,121,9,'en|121|9'),(2905,'vi',NULL,'<div class=\"perfume-details\">\n    <div class=\"perfume-section story-section mb-6\">\n        <h3 class=\"text-xl font-bold text-gray-800 mb-2\">1. Câu Chuyện & Cảm Hứng Mùi Hương</h3>\n        <p class=\"text-gray-600 leading-relaxed\">Dung tích chiết 10ml tiện lợi chuẩn từ chai gốc Creed Aventus chính hãng, cho bạn thoải mái trải nghiệm mùi hương đỉnh cao của bậc vương giả mọi lúc mọi nơi.</p>\n    </div>\n\n    <div class=\"perfume-section notes-section mb-6\">\n        <h3 class=\"text-xl font-bold text-gray-800 mb-3\">2. Kim Tự Tháp 3 Tầng Hương Chuẩn Hãng</h3>\n        <ul class=\"list-disc pl-5 space-y-2 text-gray-600\">\n            <li><strong>Hương đầu (Top Notes):</strong> Quả dứa nướng, Cam Bergamot, Quả lý chua đen, Táo xanh</li>\n            <li><strong>Hương giữa (Heart Notes):</strong> Gỗ bạch dương hun khói, Hoắc hương, Hoa hồng, Hoa nhài</li>\n            <li><strong>Hương cuối (Base Notes):</strong> Xạ hương biển, Long diên hương hoàng gia, Rêu sồi, Vani</li>\n        </ul>\n    </div>\n\n    <div class=\"perfume-section specs-section mb-6\">\n        <h3 class=\"text-xl font-bold text-gray-800 mb-3\">3. Thông Số Kỹ Thuật & Hoàn Cảnh Sử Dụng</h3>\n        <div class=\"grid grid-cols-2 gap-3 text-sm text-gray-700 bg-gray-50 p-4 rounded-lg\">\n            <div><strong>Thương hiệu:</strong> Creed</div>\n            <div><strong>Xuất xứ:</strong> Pháp</div>\n            <div><strong>Nồng độ:</strong> Eau de Parfum (EDP)</div>\n            <div><strong>Dung tích:</strong> 10ml</div>\n            <div><strong>Nhóm hương:</strong> Hương Cam Chanh Tươi Mát</div>\n            <div><strong>Phong cách:</strong> Hoàng gia, Đẳng cấp bỏ túi, Tiện dụng du lịch</div>\n            <div><strong>Độ lưu hương:</strong> Lưu hương 8 – 10 giờ</div>\n            <div><strong>Độ tỏa hương:</strong> Tỏa hương tốt trong bán kính 1.5 mét</div>\n        </div>\n    </div>\n\n    <div class=\"perfume-section guarantee-section mb-4\">\n        <h3 class=\"text-xl font-bold text-gray-800 mb-2\">4. Hướng Dẫn Sử Dụng & Cam Kết Chính Hãng</h3>\n        <p class=\"text-gray-600 leading-relaxed mb-2\">\n            Xịt trực tiếp lên các điểm mạch trên cơ thể như cổ tay, sau gáy, ngực và hai bên mang tai để nhiệt độ cơ thể giúp khuếch tán mùi hương tốt nhất. Bảo quản nơi khô ráo, thoáng mát, tránh ánh nắng trực tiếp.\n        </p>\n        <div class=\"p-3 bg-green-50 border-l-4 border-green-500 text-green-800 text-sm font-medium\">\n            ✔ Cam kết 100% sản phẩm chính hãng nhập khẩu nguyên seal/chiết trực tiếp từ chai gốc. Bồi hoàn 200% nếu phát hiện hàng giả.\n        </div>\n    </div>\n</div>',NULL,NULL,NULL,NULL,NULL,NULL,121,10,'vi|121|10'),(2906,'en',NULL,'<p>Decant Creed Aventus EDP 10ml delivers luxury, long-lasting performance up to 12 hours. 100% authentic guarantee.</p>',NULL,