INSERT INTO `theme_section_translations` VALUES (2,2,'en','{\"css\": \".home-offer h1 {\\n  display: block;\\n  font-weight: 1000;\\n  text-align: center;\\n  font-size: 22px;\\n  font-family: \\\"Playfair Display\\\", \\\"Times New Roman\\\", serif;\\n  background-color: #e8edfe;\\n  padding-top: 20px;\\n  padding-bottom: 20px;\\n}\\n\\n@media (max-width: 768px) {\\n  .home-offer h1 {\\n    font-size: 18px;\\n    padding-top: 10px;\\n    padding-bottom: 10px;\\n  }\\n} \\n\\n@media (max-width: 525px) {\\n  .home-offer h1 {\\n    font-size: 14px;\\n    padding-top: 6px;\\n    padding-bottom: 6px;\\n  }\\n}\", \"html\": \"<div class=\\\"home-offer\\\"><h1>UP TO 40% OFF - PREMIER GAMING GEAR & TECH STORE</h1></div>\"}',NULL),(7,12,'en','{\"services\": [{\"title\": \"Free Express Shipping\", \"description\": \"Fast & secure nationwide delivery\", \"service_icon\": \"icon-truck\"}, {\"title\": \"100% Genuine Gear\", \"description\": \"12-month official replacement warranty\", \"service_icon\": \"icon-product\"}, {\"title\": \"24/7 Customer Support\", \"description\": \"Dedicated assistance around the clock\", \"service_icon\": \"icon-support\"}]}',NULL),(10,16,'en','{\"filters\": []}',NULL),(12,18,'en','{\"title\": \"Featured Products\", \"filters\": {\"limit\": \"12\", \"featured\": \"1\"}}',NULL),(13,19,'en','{\"images\": [{\"link\": \"\", \"image\": \"storage/themes/default/sections/19/acrpKL0hcAb66rOjph50MkDSCUY2SC2spx1zWq3K.webp\", \"title\": \"\"}, {\"link\": \"\", \"image\": \"storage/themes/default/sections/19/DPrdA7D9jK9Qxo2iwe46EoEWOx4B39FwcN5y3fbS.webp\", \"title\": \"\"}, {\"link\": \"\", \"image\": \"storage/themes/default/sections/19/jI6aLk19UTl7ado1Pu1tg8crvPHLTuLimJkCeYwg.webp\", \"title\": \"\"}]}',NULL),(15,22,'en','{\"css\": \"/* Container wrapper */\\n.siuu-banner-wrapper {\\n  width: 100%;\\n  padding: 40px 16px;\\n  display: flex;\\n  justify-content: center;\\n  align-items: center;\\n  box-sizing: border-box;\\n}\\n\\n/* Promo banner frame */\\n.siuu-promo-banner {\\n  display: flex;\\n  flex-direction: row;\\n  width: 100%;\\n  max-width: 1240px;\\n  min-height: 420px;\\n  border-radius: 16px;\\n  overflow: hidden;\\n  box-shadow: 0 10px 25px -5px rgba(0, 0, 0, 0.1);\\n  background-color: #0b111e;\\n}\\n\\n/* Left image column */\\n.siuu-banner-image {\\n  flex: 1.1;\\n  position: relative;\\n  background-color: #f1f5f9;\\n  overflow: hidden;\\n}\\n\\n.siuu-banner-image img {\\n  width: 100%;\\n  height: 100%;\\n  object-fit: cover;\\n  display: block;\\n}\\n\\n/* Right content column */\\n.siuu-banner-content {\\n  flex: 0.9;\\n  background-color: #0b111e;\\n  color: #ffffff;\\n  padding: 48px;\\n  display: flex;\\n  flex-direction: column;\\n  justify-content: center;\\n  align-items: flex-start;\\n  box-sizing: border-box;\\n}\\n\\n.siuu-tagline {\\n  font-size: 0.875rem;\\n  font-weight: 600;\\n  text-transform: uppercase;\\n  letter-spacing: 1.5px;\\n  color: #94a3b8;\\n  margin-bottom: 12px;\\n}\\n\\n.siuu-title {\\n  font-size: 2rem;\\n  line-height: 1.3;\\n  font-weight: 800;\\n  color: #ffffff;\\n  margin-bottom: 16px;\\n}\\n\\n.siuu-desc {\\n  font-size: 0.95rem;\\n  line-height: 1.6;\\n  color: #cbd5e1;\\n  margin-bottom: 28px;\\n}\\n\\n.siuu-btn {\\n  display: inline-block;\\n  background-color: #2563eb;\\n  color: #ffffff !important;\\n  font-size: 0.95rem;\\n  font-weight: 600;\\n  padding: 12px 28px;\\n  border-radius: 8px;\\n  text-decoration: none;\\n  transition: background-color 0.2s ease;\\n}\\n\\n.siuu-btn:hover {\\n  background-color: #1d4ed8;\\n}\\n\\n/* Mobile responsive */\\n@media (max-width: 768px) {\\n  .siuu-promo-banner {\\n    flex-direction: column;\\n  }\\n  .siuu-banner-image {\\n    min-height: 240px;\\n  }\\n  .siuu-banner-content {\\n    padding: 28px 20px;\\n  }\\n  .siuu-title {\\n    font-size: 1.5rem;\\n  }\\n}\", \"html\": \"<div class=\\\"siuu-banner-wrapper\\\">\\r\\n  <div class=\\\"siuu-promo-banner\\\">\\r\\n    \\r\\n    <div class=\\\"siuu-banner-image\\\">\\r\\n      <img src=\\\"https://images.unsplash.com/photo-1615663245857-ac93bb7c39e7?q=80&amp;w=1000&amp;auto=format&amp;fit=crop\\\" alt=\\\"Mousepad &amp; Gaming Mouse ShopSiuu\\\" />\\r\\n    </div>\\r\\n\\r\\n    \\r\\n    <div class=\\\"siuu-banner-content\\\">\\r\\n      <span class=\\\"siuu-tagline\\\">ShopSiuu Showroom</span>\\r\\n      <h2 class=\\\"siuu-title\\\">Don\'t just trust the hype,<br />feel the gear yourself</h2>\\r\\n      <p class=\\\"siuu-desc\\\">\\r\\n        Over 200 gaming gear models ready for hands-on trial and side-by-side comparison on-site. Friendly, zero-pressure advice.\\r\\n      </p>\\r\\n      <a href=\\\"http://127.0.0.1:8000/search?featured=1\\\" class=\\\"siuu-btn\\\">Visit ShopSiuu</a>\\r\\n    </div>\\r\\n  </div>\\r\\n</div>\"}',NULL),(16,23,'en','{\"title\": \"Featured Audio & Earbuds\", \"filters\": {\"sort\": \"created_at-desc\", \"category_id\": \"5\"}}',NULL),(18,25,'en','{\"title\": \"Gaming Gear & Accessories\", \"filters\": {\"category_id\": \"6\"}}',NULL),(19,26,'en','{\"css\": \".siuu-footer-wrapper {\\n  width: 100%;\\n  background-color: #f8fafc;\\n  border-top: 1px solid #e2e8f0;\\n  padding: 30px 20px 20px !important; /* Compact padding */\\n  margin-bottom: 0 !important;\\n  box-sizing: border-box;\\n}\\n\\n.siuu-footer-container {\\n  max-width: 1240px;\\n  margin: 0 auto;\\n  display: flex;\\n  justify-content: space-between;\\n  flex-wrap: wrap;\\n  gap: 20px;\\n}\\n\\n.siuu-footer-col {\\n  flex: 1 1 220px;\\n}\\n\\n.siuu-f-title {\\n  font-size: 0.95rem;\\n  font-weight: 700;\\n  color: #0f172a;\\n  margin-bottom: 12px;\\n  text-transform: uppercase;\\n}\\n\\n.siuu-f-desc, .siuu-f-info {\\n  font-size: 0.85rem;\\n  line-height: 1.5;\\n  color: #64748b;\\n  margin-bottom: 8px;\\n}\\n\\n.siuu-f-links {\\n  list-style: none;\\n  padding: 0;\\n  margin: 0;\\n}\\n\\n.siuu-f-links li {\\n  margin-bottom: 8px;\\n}\\n\\n.siuu-f-links a {\\n  text-decoration: none;\\n  color: #475569;\\n  font-size: 0.875rem;\\n  transition: color 0.2s;\\n}\\n\\n.siuu-f-links a:hover {\\n  color: #2563eb;\\n}\\n\\n/* Email subscribe form styling */\\n.siuu-f-form {\\n  display: flex !important;\\n  align-items: center;\\n  margin-top: 10px;\\n  margin-bottom: 10px;\\n  width: 100%;\\n  max-width: 280px;\\n}\\n\\n.siuu-f-input {\\n  flex: 1 !important;\\n  display: block !important;\\n  height: 38px !important;\\n  padding: 0 12px !important;\\n  border: 1px solid #cbd5e1 !important;\\n  border-radius: 6px 0 0 6px !important;\\n  outline: none !important;\\n  background-color: #ffffff !important;\\n  color: #0f172a !important;\\n  font-size: 0.875rem !important;\\n  box-sizing: border-box !important;\\n}\\n\\n.siuu-f-btn {\\n  height: 38px !important;\\n  background-color: #2563eb !important;\\n  color: #ffffff !important;\\n  border: none !important;\\n  padding: 0 16px !important;\\n  border-radius: 0 6px 6px 0 !important;\\n  cursor: pointer;\\n  font-weight: 600;\\n  font-size: 0.875rem !important;\\n  box-sizing: border-box !important;\\n  white-space: nowrap;\\n}\\n\\n.siuu-f-badge {\\n  font-size: 0.8rem;\\n  color: #16a34a;\\n  font-weight: 600;\\n}\\n\\n@media (max-width: 768px) {\\n  .siuu-footer-container {\\n    flex-direction: column;\\n  }\\n}\", \"html\": \"<div class=\\\"siuu-footer-wrapper\\\">\\r\\n  <div class=\\\"siuu-footer-container\\\">\\r\\n    \\r\\n    <div class=\\\"siuu-footer-col\\\">\\r\\n      <h3 class=\\\"siuu-f-title\\\">ShopSiuu Gaming Gear</h3>\\r\\n      <p class=\\\"siuu-f-desc\\\">Authorized distributor of authentic gaming gear & high-end peripherals.</p>\\r\\n      <p class=\\\"siuu-f-info\\\"><strong>Address:</strong> 127e Le Lu, Tan Phu District, Ho Chi Minh City</p>\\r\\n      <p class=\\\"siuu-f-info\\\"><strong>Hotline:</strong> 0909 xxx xxx (08:30 - 21:30)</p>\\r\\n    </div>\\r\\n\\r\\n    \\r\\n    <div class=\\\"siuu-footer-col\\\">\\r\\n      <h3 class=\\\"siuu-f-title\\\">Customer Support</h3>\\r\\n      <ul class=\\\"siuu-f-links\\\">\\r\\n        <li><a href=\\\"/page/about-us\\\">About Us</a></li>\\r\\n        <li><a href=\\\"/page/customer-service\\\">Customer Service</a></li>\\r\\n        <li><a href=\\\"/page/terms-of-use\\\">Terms of Use</a></li>\\r\\n      </ul>\\r\\n    </div>\\r\\n\\r\\n    \\r\\n    <div class=\\\"siuu-footer-col\\\">\\r\\n      <h3 class=\\\"siuu-f-title\\\">Store Policies</h3>\\r\\n      <ul class=\\\"siuu-f-links\\\">\\r\\n        <li><a href=\\\"/page/privacy-policy\\\">Privacy Policy</a></li>\\r\\n        <li><a href=\\\"/page/shipping-policy\\\">Shipping Policy</a></li>\\r\\n        <li><a href=\\\"/page/return-policy\\\">Return & Exchange Policy</a></li>\\r\\n      </ul>\\r\\n    </div>\\r\\n\\r\\n    \\r\\n    <div class=\\\"siuu-footer-col\\\">\\r\\n      <h3 class=\\\"siuu-f-title\\\">Newsletter</h3>\\r\\n      <p class=\\\"siuu-f-desc\\\">Subscribe to receive a 10% discount voucher for your first order.</p>\\r\\n      <div class=\\\"siuu-f-form\\\">\\r\\n        \\r\\n        <button type=\\\"button\\\" class=\\\"siuu-f-btn\\\">Subscribe</button>\\r\\n      </div>\\r\\n      <p class=\\\"siuu-f-badge\\\">✓ 100% Genuine Guarantee</p>\\r\\n    </div>\\r\\n  </div>\\r\\n</div>\"}',NULL),(20,27,'en','{\"column_1\": [{\"url\": \"http://localhost:8000/page/about-us\", \"title\": \"About Us\"}, {\"url\": \"http://localhost:8000/page/customer-service\", \"title\": \"Customer Service\"}, {\"url\": \"http://localhost:8000/page/whats-new\", \"title\": \"New Arrivals & Trends\"}, {\"url\": \"http://localhost:8000/page/terms-of-use\", \"title\": \"Terms of Use\"}, {\"url\": \"http://localhost:8000/page/terms-conditions\", \"title\": \"Terms & Conditions\"}], \"column_2\": [{\"url\": \"http://localhost:8000/page/privacy-policy\", \"title\": \"Privacy Policy\"}, {\"url\": \"http://localhost:8000/page/payment-policy\", \"title\": \"Payment Policy\"}, {\"url\": \"http://localhost:8000/page/shipping-policy\", \"title\": \"Shipping Policy\"}, {\"url\": \"http://localhost:8000/page/r